package com.example.myexodus.backup

import java.io.ByteArrayInputStream
import org.junit.Assert.assertArrayEquals
import org.junit.Assert.assertEquals
import org.junit.Assert.assertThrows
import org.junit.Test

/**
 * Account plan §8.5: the AAD layouts and the v1 header are byte-exact fixtures. These hex
 * strings are hand-transcribed from the plan, not generated by the code under test.
 */
class BackupEnvelopeTest {

    private fun hex(value: String): ByteArray =
        value.chunked(2).map { it.toInt(16).toByte() }.toByteArray()

    private fun toHex(value: ByteArray): String = value.joinToString("") { "%02x".format(it) }

    private val backupId = (0x00..0x0f).map { it.toByte() }.toByteArray()
    private val keyId = (0xa0..0xaf).map { it.toByte() }.toByteArray()

    @Test
    fun payloadAad_isTheExactPlanLayout() {
        val expected = hex(
            "4d5945584f4455532d4241434b55502d5041594c4f41442d563100" + // MYEXODUS-BACKUP-PAYLOAD-V1\0
                "0008" + // uint16 uid length
                "757365722d313233" + // "user-123"
                "000102030405060708090a0b0c0d0e0f" + // backup ID
                "00000007" + // uint32 schema version
                "0001", // uint16 envelope version
        )

        val actual = BackupEnvelope.payloadAad("user-123", backupId, schemaVersion = 7)

        assertArrayEquals(expected, actual)
    }

    @Test
    fun dekWrapAad_isTheExactPlanLayout() {
        val expected = hex(
            "4d5945584f4455532d4241434b55502d44454b2d575241502d563100" + // MYEXODUS-BACKUP-DEK-WRAP-V1\0
                "0008" +
                "757365722d313233" +
                "000102030405060708090a0b0c0d0e0f" +
                "a0a1a2a3a4a5a6a7a8a9aaabacadaeaf" + // key ID
                "0001",
        )

        val actual = BackupEnvelope.dekWrapAad("user-123", backupId, keyId)

        assertArrayEquals(expected, actual)
    }

    @Test
    fun uidLength_isUnsignedBigEndianAndBounded() {
        val longest = "a".repeat(0xFFFF)
        val aad = BackupEnvelope.payloadAad(longest, backupId, schemaVersion = 1)
        assertEquals("ffff", toHex(aad.copyOfRange(27, 29)))

        assertThrows(IllegalArgumentException::class.java) {
            BackupEnvelope.payloadAad("a".repeat(0x10000), backupId, schemaVersion = 1)
        }
        assertThrows(IllegalArgumentException::class.java) {
            BackupEnvelope.payloadAad("", backupId, schemaVersion = 1)
        }
    }

    @Test
    fun header_rejectsWrongLengthMagicAndVersion() {
        val header = ByteArray(BackupEnvelope.HEADER_BYTES)
        BackupEnvelope.MAGIC.copyInto(header)
        header[9] = 1 // version 1
        setU64(header, header.size - 8, BackupEnvelope.TAG_BYTES.toLong())

        val valid = BackupEnvelope.parseHeader(header)
        org.junit.Assert.assertTrue(valid is BackupEnvelope.ParseResult.Valid)

        assertEquals(
            BackupEnvelope.ParseResult.Invalid(BackupEnvelope.Reason.INVALID_LENGTH),
            BackupEnvelope.parseHeader(header.copyOf(header.size - 1)),
        )

        val badMagic = header.copyOf()
        badMagic[0] = 'X'.code.toByte()
        assertEquals(
            BackupEnvelope.ParseResult.Invalid(BackupEnvelope.Reason.BAD_MAGIC),
            BackupEnvelope.parseHeader(badMagic),
        )

        val badVersion = header.copyOf()
        badVersion[9] = 2
        assertEquals(
            BackupEnvelope.ParseResult.Invalid(BackupEnvelope.Reason.UNSUPPORTED_VERSION),
            BackupEnvelope.parseHeader(badVersion),
        )
    }

    @Test
    fun header_rejectsPayloadLengthBelowTagOrAboveCap() {
        val header = ByteArray(BackupEnvelope.HEADER_BYTES)
        BackupEnvelope.MAGIC.copyInto(header)
        header[9] = 1
        setU64(header, header.size - 8, BackupEnvelope.TAG_BYTES - 1L)
        assertEquals(
            BackupEnvelope.ParseResult.Invalid(BackupEnvelope.Reason.INVALID_LENGTH),
            BackupEnvelope.parseHeader(header),
        )

        setU64(header, header.size - 8, BackupEnvelope.MAX_COMPRESSED_BYTES + BackupEnvelope.TAG_BYTES + 1)
        assertEquals(
            BackupEnvelope.ParseResult.Invalid(BackupEnvelope.Reason.INVALID_LENGTH),
            BackupEnvelope.parseHeader(header),
        )

        setU64(header, header.size - 8, Long.MIN_VALUE)
        assertEquals(
            BackupEnvelope.ParseResult.Invalid(BackupEnvelope.Reason.INVALID_LENGTH),
            BackupEnvelope.parseHeader(header),
        )
    }

    @Test
    fun readHeader_reportsTruncationInsteadOfAPartialHeader() {
        val header = ByteArray(BackupEnvelope.HEADER_BYTES)
        BackupEnvelope.MAGIC.copyInto(header)
        header[9] = 1

        val result = BackupEnvelope.readHeader(
            ByteArrayInputStream(header.copyOf(BackupEnvelope.HEADER_BYTES - 1)),
        )

        assertEquals(
            BackupEnvelope.ParseResult.Invalid(BackupEnvelope.Reason.TRUNCATED),
            result,
        )
    }

    private fun setU64(bytes: ByteArray, offset: Int, value: Long) {
        for (i in 0 until 8) {
            bytes[offset + i] = (value ushr (56 - 8 * i)).toByte()
        }
    }
}
